import { Button } from 'primereact/button';
import { generateMetrics } from '../services/api';
import { useState } from 'react';

export default function MetricGenerator({ onGenerated }) {
  const [loading, setLoading] = useState(false);

  const handleGenerate = async () => {
    setLoading(true);
    try {
      await generateMetrics();
      onGenerated?.();
    } catch (error) {
      console.error('Помилка генерації метрик:', error);
      // можна показати повідомлення про помилку через toast, якщо хочеш
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="card">
      <h3>Generate Metrics</h3>
      <Button label="Generate" icon="pi pi-cog" onClick={handleGenerate} loading={loading} />
    </div>
  );
}
